const BASE = 'https://www.themealdb.com/api/json/v1/1'

export interface MealSummary {
  idMeal: string
  strMeal: string
  strMealThumb: string
}

export interface Meal extends MealSummary {
  strCategory: string | null
  strArea: string | null
  strInstructions: string | null
  strYoutube: string | null
  strSource: string | null
  [key: string]: string | null
}

export interface Ingredient {
  name: string
  measure: string
}

export interface Filters {
  q: string
  c: string
  a: string
}

async function getJson<T>(path: string, signal?: AbortSignal): Promise<T> {
  const res = await fetch(`${BASE}/${path}`, { signal })
  if (!res.ok) throw new Error(`Server resep menjawab ${res.status}`)
  return (await res.json()) as T
}

// Tidak ada hasil dijawab {"meals": null}, id yang bukan angka dijawab
// {"meals": "Invalid ID"}. Apa pun selain array kita anggap kosong.
async function getMeals<T>(path: string, signal?: AbortSignal): Promise<T[]> {
  const data = await getJson<{ meals: unknown }>(path, signal)
  return Array.isArray(data.meals) ? data.meals : []
}

// API gratis hanya bisa satu filter per request. Kalau ada beberapa,
// ambil semuanya bersamaan lalu sisakan resep yang muncul di setiap daftar.
export async function findMeals(f: Filters, signal?: AbortSignal): Promise<MealSummary[]> {
  const q = f.q.trim()
  const requests: Promise<MealSummary[]>[] = []
  if (q || (!f.c && !f.a)) requests.push(getMeals(`search.php?s=${encodeURIComponent(q)}`, signal))
  if (f.c) requests.push(getMeals(`filter.php?c=${encodeURIComponent(f.c)}`, signal))
  if (f.a) requests.push(getMeals(`filter.php?a=${encodeURIComponent(f.a)}`, signal))
  const [first = [], ...rest] = await Promise.all(requests)
  return first.filter((m) => rest.every((list) => list.some((x) => x.idMeal === m.idMeal)))
}

export async function getMeal(id: string, signal?: AbortSignal): Promise<Meal | null> {
  const meals = await getMeals<Meal>(`lookup.php?i=${encodeURIComponent(id)}`, signal)
  return meals[0] ?? null
}

export async function getCategories(signal?: AbortSignal): Promise<string[]> {
  const rows = await getMeals<{ strCategory: string }>('list.php?c=list', signal)
  return rows.map((r) => r.strCategory).sort()
}

export async function getAreas(signal?: AbortSignal): Promise<string[]> {
  const rows = await getMeals<{ strArea: string }>('list.php?a=list', signal)
  // Daftar aslinya berisi nama ganda, padahal key di v-for harus unik.
  return [...new Set(rows.map((r) => r.strArea))].sort()
}

export function parseIngredients(meal: Meal): Ingredient[] {
  const list: Ingredient[] = []
  for (let i = 1; i <= 20; i++) {
    const name = meal[`strIngredient${i}`]?.trim()
    if (!name) continue
    list.push({ name, measure: meal[`strMeasure${i}`]?.trim() ?? '' })
  }
  return list
}

import { vi } from 'vitest'
import { createMemoryHistory, createRouter } from 'vue-router'
import HomeView from '@/views/HomeView.vue'
import RecipeView from '@/views/RecipeView.vue'

// fetch palsu: jawab berdasarkan path setelah /api/json/v1/1/
export function mockApi(routes: Record<string, unknown>, status = 200) {
  const fn = vi.fn(async (url: string) => {
    const path = url.split('/api/json/v1/1/')[1] ?? ''
    const body = path in routes ? routes[path] : { meals: null }
    return new Response(JSON.stringify(body), { status })
  })
  vi.stubGlobal('fetch', fn)
  return fn
}

export function makeRouter() {
  return createRouter({
    history: createMemoryHistory(),
    routes: [
      { path: '/', name: 'home', component: HomeView },
      { path: '/resep/:id', name: 'recipe', component: RecipeView, props: true },
    ],
  })
}

export const meal = (id: string, name: string) => ({
  idMeal: id,
  strMeal: name,
  strMealThumb: `https://img.test/${id}.jpg`,
})

