import { computed, ref, watch } from 'vue'
import { defineStore } from 'pinia'
import type { MealSummary } from '@/api/mealdb'

const KEY = 'resep-favorit'

function load(): MealSummary[] {
  try {
    const saved: unknown = JSON.parse(localStorage.getItem(KEY) ?? '[]')
    return Array.isArray(saved) ? saved : []
  } catch {
    return [] // isi localStorage rusak: mulai dari kosong, jangan bikin aplikasi mati
  }
}

export const useFavoritesStore = defineStore('favorites', () => {
  const items = ref<MealSummary[]>(load())
  const ids = computed(() => new Set(items.value.map((m) => m.idMeal)))
  const count = computed(() => items.value.length)

  function isFavorite(id: string) {
    return ids.value.has(id)
  }

  function toggle(meal: MealSummary) {
    if (isFavorite(meal.idMeal)) {
      items.value = items.value.filter((m) => m.idMeal !== meal.idMeal)
    } else {
      // Simpan seperlunya saja, bukan seluruh resep yang berisi 50-an field.
      const { idMeal, strMeal, strMealThumb } = meal
      items.value = [...items.value, { idMeal, strMeal, strMealThumb }]
    }
  }

  watch(items, (v) => {
    try {
      localStorage.setItem(KEY, JSON.stringify(v))
    } catch {
      // penyimpanan penuh atau diblokir: favorit tetap jalan selama tab terbuka
    }
  })

  return { items, count, isFavorite, toggle }
})

import { beforeEach, describe, expect, it } from 'vitest'
import { nextTick } from 'vue'
import { createPinia, setActivePinia } from 'pinia'
import { useFavoritesStore } from '@/stores/favorites'
import { meal } from './helpers'

beforeEach(() => {
  localStorage.clear()
  setActivePinia(createPinia())
})

describe('favorites store', () => {
  it('menyimpan dan menghapus favorit di localStorage', async () => {
    const store = useFavoritesStore()
    store.toggle({ ...meal('7', 'Rendang'), strCategory: 'Beef' } as never)
    await nextTick()
    expect(store.isFavorite('7')).toBe(true)
    expect(JSON.parse(localStorage.getItem('resep-favorit')!)).toEqual([meal('7', 'Rendang')])

    store.toggle(meal('7', 'Rendang'))
    await nextTick()
    expect(store.count).toBe(0)
    expect(localStorage.getItem('resep-favorit')).toBe('[]')
  })

  it('membaca favorit yang tersimpan dan tahan terhadap isi rusak', () => {
    localStorage.setItem('resep-favorit', JSON.stringify([meal('9', 'Soto')]))
    expect(useFavoritesStore().count).toBe(1)

    localStorage.setItem('resep-favorit', '{rusak')
    setActivePinia(createPinia())
    expect(useFavoritesStore().count).toBe(0)
  })
})

import { ref, shallowRef, toValue, watch, type MaybeRefOrGetter } from 'vue'

// Jalankan load() setiap kali key berubah. Request lama dibatalkan
// supaya jawaban yang telat tidak menimpa hasil yang lebih baru.
export function useFetch<K, T>(key: MaybeRefOrGetter<K>, load: (key: K, signal: AbortSignal) => Promise<T>) {
  const data = shallowRef<T | null>(null)
  const error = ref<string | null>(null)
  const loading = ref(false)
  const attempt = ref(0) // dinaikkan oleh reload() untuk tombol "Coba lagi"

  watch(
    () => [toValue(key), attempt.value] as const,
    async ([k], _old, onCleanup) => {
      const controller = new AbortController()
      onCleanup(() => controller.abort())
      loading.value = true
      let result: T | null = null
      let message: string | null = null
      try {
        result = await load(k, controller.signal)
      } catch (e) {
        message = e instanceof Error ? e.message : String(e)
      }
      if (controller.signal.aborted) return // sudah ada request yang lebih baru
      data.value = result
      error.value = message
      loading.value = false
    },
    { immediate: true },
  )

  return { data, error, loading, reload: () => attempt.value++ }
}

export function debounce<A extends unknown[]>(fn: (...args: A) => void, ms: number) {
  let timer: ReturnType<typeof setTimeout> | undefined
  const run = (...args: A) => {
    clearTimeout(timer)
    timer = setTimeout(() => fn(...args), ms)
  }
  run.cancel = () => clearTimeout(timer)
  return run
}

import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest'
import { flushPromises, mount } from '@vue/test-utils'
import { createPinia } from 'pinia'
import App from '@/App.vue'
import { makeRouter, meal, mockApi } from './helpers'

async function mountAt(url: string) {
  const router = makeRouter()
  router.push(url)
  await router.isReady()
  const wrapper = mount(App, { global: { plugins: [router, createPinia()] } })
  await flushPromises()
  return { wrapper, router }
}

beforeEach(() => localStorage.clear())
afterEach(() => {
  vi.unstubAllGlobals()
  vi.useRealTimers()
})

describe('HomeView', () => {
  it('menampilkan hasil pencarian dari ?q= di URL', async () => {
    mockApi({ 'search.php?s=chicken': { meals: [meal('1', 'Chicken Soup'), meal('2', 'Chicken Katsu')] } })
    const { wrapper } = await mountAt('/?q=chicken')
    expect(wrapper.find('input[type=search]').element).toHaveProperty('value', 'chicken')
    expect(wrapper.findAll('.card h3').map((h) => h.text())).toEqual(['Chicken Soup', 'Chicken Katsu'])
    expect(wrapper.text()).toContain('2 resep cocok')
  })

  it('menampilkan keadaan kosong dan bisa menghapus filter', async () => {
    mockApi({ 'filter.php?a=Indonesian': { meals: null } })
    const { wrapper, router } = await mountAt('/?a=Indonesian')
    expect(wrapper.text()).toContain('Tidak ada resep yang cocok')
    await wrapper.get('button.btn').trigger('click')
    await flushPromises()
    expect(router.currentRoute.value.query).toEqual({})
  })

  it('menampilkan error lalu pulih lewat tombol Coba lagi', async () => {
    mockApi({}, 500)
    const { wrapper } = await mountAt('/?q=pasta')
    expect(wrapper.text()).toContain('Resep gagal dimuat')

    mockApi({ 'search.php?s=pasta': { meals: [meal('5', 'Pasta Pesto')] } })
    await wrapper.get('button.btn').trigger('click')
    await flushPromises()
    expect(wrapper.findAll('.card')).toHaveLength(1)
  })

  it('menunggu 400 ms setelah berhenti mengetik sebelum mengubah URL', async () => {
    vi.useFakeTimers({ toFake: ['setTimeout', 'clearTimeout'] })
    const fetch = mockApi({ 'search.php?s=': { meals: [] } })
    const { wrapper, router } = await mountAt('/')
    const input = wrapper.get('input[type=search]')

    await input.setValue('pas')
    await input.setValue('pasta')
    vi.advanceTimersByTime(399)
    await flushPromises()
    expect(router.currentRoute.value.query.q).toBeUndefined()

    vi.advanceTimersByTime(1)
    await flushPromises()
    expect(router.currentRoute.value.query.q).toBe('pasta')
    expect(fetch.mock.calls.filter(([url]) => url.includes('search.php?s=pas')).map(([url]) => url)).toEqual([
      'https://www.themealdb.com/api/json/v1/1/search.php?s=pasta',
    ])
  })

  it('tombol hati menambah hitungan favorit di header', async () => {
    mockApi({ 'search.php?s=': { meals: [meal('3', 'Gado-gado')] } })
    const { wrapper } = await mountAt('/')
    await wrapper.get('.fav').trigger('click')
    expect(wrapper.get('nav').text()).toContain('Favorit (1)')
    expect(wrapper.get('.fav').attributes('aria-pressed')).toBe('true')
  })
})

